body.userscript:

            //폼초기화


            //조회


            //저장


            (function(window) {
                window.htmlentities = {
                    encode: function(str) {
                        var buf = [];

                        for (var i = str.length - 1; i >= 0; i--) {
                            buf.unshift(['&#', str[i].charCodeAt(), ';'].join(''));
                        }

                        return buf.join('');
                    },
                    decode: function(str) {
                        return str.replace(/&#(\d+);/g, function(match, dec) {
                            return String.fromCharCode(dec);
                        });
                    }
                };
            })(window);



            dataOutput.setValue("ATTACH_NO", e.attach_key);




            formObj.clear();




            clearForm();
            var so = doServiceAjax('sepoa.svc.board.SepoaQAService', 'CONNECTION', 'getDetail', {
                QNA_NUMBER: qnaNumber
            }, function(so) {76
                if (so.status == 1) {
                    var sf = new SepoaFormater(so.result[0]);
                    setData(sf);
                    dataOutput.setValue('QNA_NUMBER', qnaNumber);
                    dataOutput.setValue('mode', 'EDIT');
                } else {
                    Alert(so.message);
                }
            });




            if (!formObj.validate()) {
                Alert(Sepoa.cache.text.get('MESSAGE.0002'));
                return;
            }
            dataOutput.setValue("CONTENT", tinyMCE.activeEditor.getContent());
            if (Confirm(Sepoa.cache.text.get('MESSAGE.1018'), function(result) {
                    if (result) {
                        //dataOutput.setValue('QNA_TYPE_NAME', formObj.getSelectedOption('QNA_TYPE'));
                        var so = doServiceAjax('sepoa.svc.board.SepoaQAService', 'TRANSACTION', 'doSave', null, function(so) {
                            if (so.status == 1) {
                                Alert(Sepoa.cache.text.get('MESSAGE.0054'));
                                callFunction('QA_002', 'changeFrame', ['list']);
                            } else {
                                Alert(so.message);
                            }
                        });
                    }
                }));




            ed.on('init', function(args) {
                if (Sepoa.request.QNA_NUMBER) doQuery(Sepoa.request.QNA_NUMBER);
            });




            if (!sf) {
                sf = tempData;
            } else {
                tempData = sf;
            }
            if (!sf) return;
            var c = '';
            if(sf.getValue('CONTENT') != undefined){
	            c = sf.getValue('CONTENT').replaceAll("\\\"", "\"");
            }
            if (!tempData) {
                clearForm();
            } else {
                formObj.dataMapper(sf);
                vaultObj.setAttachKey(sf.getValue('ATTACH_NO', 0));
                tinyMCE.activeEditor.setContent(c);
            }





            var target = formObj.getContainer("EDITOR_BOX");
            var height = document.body.offsetHeight - dhx.absTop(formObj.getContainer("EDITOR_BOX")) - 80;
            target.style.height = height + 'px';
            target.style.border = 'solid 1px rgba(0,0,0,0.2)';




            tinymceReady = true;
            if (tinymceContent != '') {
                tinyMCE.activeEditor.setContent(tinymceContent);
            }

            if (formObj.getValue('NOTICE_NUMBER') != '') {
                changeMode('view');
            } else {
                changeMode('insert');
            }
            editorResize();




            var f = tinyMCE.activeEditor.iframeElement;
            tinyMCE.activeEditor.iframeElement.style.height = $('.sepoa-editor-wrapper')[0].offsetHeight - f.offsetTop - 5 + "px"




            btnObj.showButton(null, false)
            if (mode == 'view') {
                tinyMCE.activeEditor.setMode("readonly")
                formObj.setViewMode(true);
                formObj.showItem('NOTICE_NUMBER');
                btnObj.showButton('add,update,delete', true)
            } else {
                tinyMCE.activeEditor.setMode("code");
                formObj.setViewMode(false);
                formObj.hideItem('NOTICE_NUMBER');
                btnObj.showButton('save,cancel', true)
            }
